import test from'node:test';import assert from'node:assert/strict';import fs from'node:fs';import path from'node:path';import os from'node:os';import{randomUUID,createHash}from'node:crypto';import{pathToFileURL}from'node:url';
const moduleRoot=process.env.DSH_PURGE_TEST_ROOT?pathToFileURL(path.resolve(process.env.DSH_PURGE_TEST_ROOT)+'/'):new URL('../',import.meta.url);const core=await import(new URL('lib/core.js',moduleRoot));
const root=fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(),'dsh-purge-core-version-'))),home=root+'/home',dir=home+'/profiles/test';fs.mkdirSync(dir,{recursive:true});const profile={name:'test',home,dir,patchPath:dir+'/cordis.patch.yml',installAnchor:root+'/package.json'};fs.writeFileSync(profile.installAnchor,'{}');const oldHome=process.env.DSH_HOME;process.env.DSH_HOME=home;
function fixture(version='0.2.1-rc.2',withBackup=true){const aiBase=dir+'/.dsh-purge-runtime/'+randomUUID()+'/node_modules/@deepseek-ai',pkg=aiBase+'/dsh-app-boot',file=pkg+'/lib/index.js';fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(pkg+'/package.json',JSON.stringify({name:'@deepseek-ai/dsh-app-boot',version}));fs.writeFileSync(file,'rc2 reviewed content\n');if(withBackup)fs.writeFileSync(file+'.dshpurge.bak','alpha OLD BACKUP\n');core.configureCommunityProfileScope(profile,{aiBase});return {aiBase,pkg,file};}
function inventory(root){const rows=[];function walk(dir){for(const e of fs.readdirSync(dir,{withFileTypes:true})){const f=path.join(dir,e.name);if(e.isDirectory())walk(f);else rows.push([path.relative(root,f),createHash('sha256').update(fs.readFileSync(f)).digest('hex')]);}}walk(root);return rows;}
const code=e=>e?.code==='DSH_PURGE_CORE_VERSION_UNSUPPORTED'&&/alpha\.1|跨版|version/i.test(e.message);
test('rc2 missing-file recovery never copies adjacent alpha bak',()=>{const{aiBase,file}=fixture();fs.unlinkSync(file);const before=inventory(aiBase);assert.throws(()=>core.restoreMissingOriginalsFromBak(aiBase),code);assert(!fs.existsSync(file));assert.deepEqual(inventory(aiBase),before);});
test('rc2 revert never overwrites current adapted implementation with old bak',async()=>{const{aiBase}=fixture(),before=inventory(aiBase);await assert.rejects(core.revertAll(aiBase),code);assert.deepEqual(inventory(aiBase),before);});
test('rc2 explicit apply cannot run even matching old recipes',async()=>{const{aiBase}=fixture(),before=inventory(aiBase);await assert.rejects(core.applyPatches(aiBase,[{id:999,name:'fixture',file:'app-boot',replacements:[{pattern:'rc2 reviewed content',replace:'BAD ALPHA PATCH'}]}]),code);assert.deepEqual(inventory(aiBase),before);});
test('rc2 backup and watched-bundle entry points refuse without writing',async()=>{const{aiBase}=fixture('0.2.1-rc.2',false),before=inventory(aiBase);await assert.rejects(core.backupAll(aiBase),code);assert.throws(()=>core.patchWatchedClientBundlesSync(aiBase),code);assert.deepEqual(inventory(aiBase),before);});
test('reviewed alpha existing behavior still restores missing file and explicitly reverts',async()=>{const{aiBase,file}=fixture('0.2.1-alpha.1');fs.unlinkSync(file);assert.deepEqual(core.restoreMissingOriginalsFromBak(aiBase),[file]);assert.equal(fs.readFileSync(file,'utf8'),'alpha OLD BACKUP\n');fs.writeFileSync(file,'current alpha modified\n');const result=await core.revertAll(aiBase);assert(result.reverted.includes(file));assert.equal(fs.readFileSync(file,'utf8'),'alpha OLD BACKUP\n');assert(!fs.existsSync(file+'.dshpurge.bak'));});
test('unknown and mixed-version private packages fail closed without destroying backup',async()=>{for(const version of['0.2.1-rc.3','0.0.0-custom']){const{aiBase}=fixture(version),before=inventory(aiBase);await assert.rejects(core.revertAll(aiBase),code);assert.deepEqual(inventory(aiBase),before);}const{aiBase}=fixture('0.2.1-alpha.1');fs.mkdirSync(aiBase+'/dsh-settings');fs.writeFileSync(aiBase+'/dsh-settings/package.json',JSON.stringify({name:'@deepseek-ai/dsh-settings',version:'0.2.1-rc.2'}));const before=inventory(aiBase);await assert.rejects(core.revertAll(aiBase),code);assert.deepEqual(inventory(aiBase),before);});
test.after(()=>{if(oldHome===undefined)delete process.env.DSH_HOME;else process.env.DSH_HOME=oldHome;fs.rmSync(root,{recursive:true,force:true});});
test('explicit profile Apply/Revert are rejected before creating owner state or touching configuration on rc2',async()=>{const{applyCurrentProfile,revertCurrentProfile}=await import(new URL('lib/community-profile.js',moduleRoot));const pkg=root+'/node_modules/@deepseek-ai/dsh-app-boot';fs.mkdirSync(pkg,{recursive:true});fs.writeFileSync(pkg+'/package.json',JSON.stringify({name:'@deepseek-ai/dsh-app-boot',version:'0.2.1-rc.2'}));const ctx={profileContext:profile,get:key=>key==='profileContext'?profile:undefined},before=inventory(home);await assert.rejects(applyCurrentProfile(ctx),code);await assert.rejects(revertCurrentProfile(ctx),code);assert.deepEqual(inventory(home),before);assert(!fs.existsSync(dir+'/.dsh-purge-runtime/owner.json'));});
test('standalone recovery CLI refuses rc2 backups before native restore or metadata change',async()=>{const{recoverCommunityProfile}=await import(new URL('lib/community-recover.js',moduleRoot));const{aiBase}=fixture(),token=path.basename(path.dirname(path.dirname(aiBase))),ownerDir=dir+'/.dsh-purge-runtime',owner='dsh-purge-community-private-runtime-v1';fs.writeFileSync(ownerDir+'/owner.json',JSON.stringify({owner,profileDir:dir}));fs.writeFileSync(ownerDir+'/current.json',JSON.stringify({owner,profileDir:dir,phase:'installed',token,aiBase,profileInstallAnchor:profile.installAnchor}));const before=inventory(home);await assert.rejects(recoverCommunityProfile(['--home',home,'--profile','test']),code);assert.deepEqual(inventory(home),before);});
test('normal plugin startup and reapply retain existing no-native-write boundary',async()=>{const index=fs.readFileSync(new URL('lib/index.js',moduleRoot),'utf8'),a=index.indexOf('export function apply(ctx, config) {'),b=index.indexOf('function applyHostHooks(',a),body=index.slice(a,b);assert(body.indexOf('applyHostHooks(ctx, cfg);\n  return;')>0);assert(body.indexOf('restoreMissingOriginalsAllHosts()')>body.indexOf('applyHostHooks(ctx, cfg);\n  return;'));assert(body.includes('cfg.autoApplyOnStart = false;'));const reapply=await import(new URL('lib/reapply.js',moduleRoot));const before=inventory(home);await assert.rejects(reapply.reapplyInstalled(),/self-reapply is disabled/);assert.deepEqual(inventory(home),before);});
test('empty, missing manifest, identity mismatch and linked private packages are not certified as supported',()=>{const{aiBase,pkg}=fixture('0.2.1-alpha.1'),before=fs.readFileSync(pkg+'/package.json');fs.unlinkSync(pkg+'/package.json');assert.throws(()=>core.restoreMissingOriginalsFromBak(aiBase),code);fs.writeFileSync(pkg+'/package.json',JSON.stringify({name:'@deepseek-ai/dsh-settings',version:'0.2.1-alpha.1'}));assert.throws(()=>core.restoreMissingOriginalsFromBak(aiBase),code);fs.writeFileSync(pkg+'/package.json',before);fs.symlinkSync(pkg,aiBase+'/dsh-linked');assert.throws(()=>core.restoreMissingOriginalsFromBak(aiBase),code);fs.unlinkSync(aiBase+'/dsh-linked');});
test('recover cannot revive an alpha private tree under a newer rc2 launcher either',async()=>{const{recoverCommunityProfile}=await import(new URL('lib/community-recover.js',moduleRoot)),{aiBase}=fixture('0.2.1-alpha.1'),ownerDir=dir+'/.dsh-purge-runtime',owner='dsh-purge-community-private-runtime-v1',token=path.basename(path.dirname(path.dirname(aiBase)));fs.writeFileSync(ownerDir+'/current.json',JSON.stringify({owner,profileDir:dir,phase:'installed',token,aiBase,profileInstallAnchor:profile.installAnchor}));const before=inventory(home);await assert.rejects(recoverCommunityProfile(['--home',home,'--profile','test']),code);assert.deepEqual(inventory(home),before);});
